{"command": "cd /workspace && cat > work/xmread.py <<'PY'
import struct, sys, numpy as np

def read_xm(path, verbose=True):
    d=open(path,'rb').read()
    o=60
    hdrsize=struct.unpack('<I',d[o:o+4])[0]
    songlen,restart,chn,pats,ins,freq,speed,bpm=struct.unpack('<HHHHHHHH',d[o+4:o+20])
    order=list(d[o+20:o+20+256])[:songlen]
    p=o+hdrsize
    P=[]
    for pi in range(pats):
        ph=struct.unpack('<I',d[p:p+4])[0]
        ptype=d[p+4]; rows=struct.unpack('<H',d[p+5:p+7])[0]; packed=struct.unpack('<H',d[p+7:p+9])[0]
        data=d[p+ph:p+ph+packed]
        cells={}
        q=0
        for r in range(rows):
            for c in range(chn):
                m=data[q]; q+=1
                note=inst=vol=eff=epp=None
                if m & 0x80:
                    note=((m>>4)&0x0f)*16 + (m&0x0f)  # guess
                    # actually standard: note = (m & 0x0f) + ((m>>4)&0x0f)... handle below
                if m & 0x01:
                    note=data[q]; q+=1
                if m & 0x02:
                    inst=data[q]; q+=1
                if m & 0x04:
                    vol=data[q]; q+=1
                if m & 0x08:
                    eff=data[q]; q+=1
                if m & 0x10:
                    epp=data[q]; q+=1
                if note or inst or vol or eff or epp:
                    cells[(r,c)]=(note,inst,vol,eff,epp)
        P.append((rows,cells))
        p+=ph+packed
    I=[]
    for ii in range(1,ins+1):
        isize=struct.unpack('<I',d[p:p+4])[0]
        name=d[p+4:p+26].rstrip(b'\0').decode('ascii',errors='replace')
        itype=d[p+26]
        nsamp=struct.unpack('<H',d[p+27:p+29])[0]
        ins_rec={'name':name,'samples':[]}
        q=p+isize
        shdr=[]
        if nsamp:
            shsz=struct.unpack('<I',d[p+29:p+33])[0]
            for s in range(nsamp):
                h=d[q:q+40]
                slen,lstart,llen=struct.unpack('<III',h[0:12])
                volume,fin=struct.unpack('<Bb',h[12:14])
                flags=h[14]; pan=h[15]; rel=struct.unpack('<b',h[16:17])[0]
                sname=h[18:40].rstrip(b'\0').decode('ascii',errors='replace')
                shdr.append(dict(len=slen,loop_start=lstart,loop_len=llen,volume=volume,finetune=fin,flags=flags,panning=pan,rel=rel,name=sname))
                q+=40
            for s in range(nsamp):
                slen=shdr[s]['len']
                raw=d[q:q+slen]; q+=slen
                if shdr[s]['flags'] & 4:
                    dd=np.frombuffer(raw,dtype='<i2').astype(np.int32)
                    x=np.cumsum(dd).astype(np.int32)
                    x=((x+32768)%65536)-32768
                    shdr[s]['pcm16']=x.astype(np.int16)
                else:
                    dd=np.frombuffer(raw,dtype=np.int8).astype(np.int32)
                    x=np.cumsum(dd)
                    x=((x+128)%256)-128
                    shdr[s]['pcm8']=x.astype(np.int8)
        p+=isize
        I.append(ins_rec)
        ins_rec['hdr']=shdr
    if verbose:
        print('songlen',songlen,'restart',restart,'chn',chn,'pats',pats,'ins',ins,'speed',speed,'bpm',bpm)
        print('order',order)
        for i,rec in enumerate(I):
            print('ins',i+1,rec['name'],[(h['name'],h['len'],h['loop_start'],h['loop_len'],h['volume'],h['finetune'],h['flags'],h['panning'],h['rel']) for h in rec['hdr']])
    return dict(songlen=songlen,restart=restart,chn=chn,speed=speed,bpm=bpm,order=order,patterns=P,instruments=I)

if __name__=='__main__':
    r=read_xm(sys.argv[1])
    for pi,(rows,cells) in enumerate(r['patterns']):
        print('--- pattern',pi,'rows',rows,'cells',len(cells))
        for k in sorted(cells)[:40]:
            print('   ',k,cells[k])
