import numpy as np

RD = 8363.0 * 2**(24/12.0)      # playback rate for note C-4 with relative note 24
P4 = 128                        # samples per C-4 cycle at RD

def bandlimit_wave(P, duty=None, kind='pulse', nharm=32):
    n = np.arange(P)/P
    x = np.zeros(P)
    H = min(nharm, P//2)
    for h in range(1, H+1):
        if kind == 'pulse':
            a = (2.0/(h*np.pi))*np.sin(np.pi*h*duty)
            ph = -np.pi*h*duty
        elif kind == 'saw':
            a = 2.0/(h*np.pi); ph = -np.pi/2
        elif kind == 'square':
            if h % 2 == 0: continue
            a = 4.0/(h*np.pi); ph = 0.0
        elif kind == 'tri':
            if h % 2 == 0: continue
            a = (8.0/(np.pi**2))*((-1)**((h-1)//2))/(h*h); ph = 0.0
        x += a*np.cos(2*np.pi*h*n + ph)
    if kind == 'pulse':
        x -= duty
    m = np.abs(x).max()
    return x/m if m > 0 else x

def rep(w, cycles):
    return np.tile(w, cycles)

def env_exp(n, tau):
    return np.exp(-np.arange(n)/(tau*RD))

def normalize(x, peak=0.98):
    m = np.abs(x).max()
    return x/m*peak if m > 0 else x

def to_int16(x):
    return np.clip(x, -1, 1)
PY
