def put(pat, row, ch, note=None, inst=None, vol=None, eff=None, epp=None):
    pat[(row,ch)] = (note, inst, vol, eff, epp)

def gate(pat, row, ch):
    """silence a channel at a row (volume column 0)"""
    cur = pat.get((row,ch))
    if cur is None or cur[0] is None:
        pat[(row,ch)] = (None, None, 0, None, None)

def write_mel(pat, mel, ch, inst, vol, bars, gate_off=True, vib=None, volmap=None):
    for (b, r, n, ln) in mel:
        if b >= bars: continue
        row = b*16 + r
        v = volmap(b, r) if volmap else vol
        put(pat, row, ch, note=N(n), inst=inst, vol=v, eff=vib[0] if (vib and ln>=4) else None,
            epp=vib[1] if (vib and ln>=4) else None)
        if gate_off:
            end = b*16 + r + ln
            if end < bars*16:
                nxt = any((bb==b and rr==r+ln) for (bb,rr,_,_) in mel)
                if not nxt: gate(pat, end, ch)

