                kc=(0,4,8,12), sr=(4,12), hc=30, ho=22, hato_rows=(2,10)):
    for b in range(bars):
        base = b*16
        if kick:
            for r in kc: put(pat, base+r, 4, note=N('C-4'), inst=I_KICK, vol=64)
        if snare:
            for r in sr: put(pat, base+r, 5, note=N('C-4'), inst=I_SNARE, vol=52)
        if hatc:
            for r in range(0,16,2): put(pat, base+r, 6, note=N('C-4'), inst=I_HATC, vol=hc)
        if hato:
            for r in hato_rows: put(pat, base+r, 7, note=N('C-4'), inst=I_HATO, vol=ho)

