# ---------------------------------------------------------- harmony data
CH = {'Am':('A-','C-','E-'), 'F':('F-','A-','C-'), 'C':('C-','E-','G-'),
      'G':('G-','B-','D-'), 'E':('E-','G#','B-')}
A_SEC = ['Am','F','C','G','Am','F','G','E']
B_SEC = ['F','G','Am','Am','F','G','C','E']
ARP_TONES = {
 'Am':['A-3','C-4','E-4','A-4'], 'F':['F-3','A-3','C-4','F-4'],
 'C':['G-3','C-4','E-4','G-4'],  'G':['G-3','B-3','D-4','G-4'],
 'E':['E-3','G#3','B-3','E-4']}
BASS_ROOT = {'Am':'A-2','F':'F-2','C':'C-2','G':'G-2','E':'E-2'}
PAD_ROOT  = {'Am':'A-3','F':'F-3','C':'C-3','G':'G-3','E':'E-3'}

A_MEL = [
 (0,0,'E-5',2),(0,2,'E-5',2),(0,4,'G-5',2),(0,6,'A-5',4),(0,10,'G-5',2),(0,12,'E-5',4),
