 (2,0,'E-5',2),(2,2,'E-5',2),(2,4,'G-5',2),(2,6,'C-6',4),(2,10,'G-5',2),(2,12,'E-5',4),
 (3,0,'D-5',2),(3,2,'D-5',2),(3,4,'G-5',2),(3,6,'B-5',4),(3,10,'A-5',2),(3,12,'G-5',4),
 (4,0,'E-5',2),(4,2,'E-5',2),(4,4,'G-5',2),(4,6,'A-5',4),(4,10,'G-5',2),(4,12,'E-5',4),
 (5,0,'F-5',2),(5,2,'F-5',2),(5,4,'A-5',2),(5,6,'C-6',4),(5,10,'D-6',2),(5,12,'C-6',4),
 (6,0,'B-5',2),(6,2,'B-5',2),(6,4,'A-5',2),(6,6,'G-5',4),(6,10,'D-5',2),(6,12,'G-5',4),
 (7,0,'E-5',2),(7,2,'G#5',2),(7,4,'B-5',2),(7,6,'E-6',6),(7,12,'B-5',2),(7,14,'G#5',2),
]
B_MEL = [
 (0,0,'A-5',4),(0,4,'C-6',4),(0,8,'F-6',7),
 (1,0,'G-5',4),(1,4,'B-5',4),(1,8,'D-6',7),
 (2,0,'A-5',4),(2,4,'C-6',4),(2,8,'E-6',7),
 (3,0,'E-6',4),(3,4,'D-6',4),(3,8,'C-6',4),(3,12,'B-5',4),
 (4,0,'A-5',4),(4,4,'C-6',4),(4,8,'F-6',7),
 (5,0,'G-5',4),(5,4,'B-5',4),(5,8,'D-6',7),
 (6,0,'E-6',4),(6,4,'G-6',4),(6,8,'E-6',7),
 (7,0,'B-5',4),(7,4,'G#5',4),(7,8,'E-6',7),
]
B_HARM = [
 (0,0,'F-5',4),(0,4,'A-5',4),(0,8,'C-6',7),
 (1,0,'E-5',4),(1,4,'G-5',4),(1,8,'B-5',7),
 (2,0,'F-5',4),(2,4,'A-5',4),(2,8,'C-6',7),
 (3,0,'C-6',4),(3,4,'B-5',4),(3,8,'A-5',4),(3,12,'G-5',4),
 (4,0,'F-5',4),(4,4,'A-5',4),(4,8,'C-6',7),
 (5,0,'E-5',4),(5,4,'G-5',4),(5,8,'B-5',7),
 (6,0,'C-6',4),(6,4,'E-6',4),(6,8,'C-6',7),
 (7,0,'G#5',4),(7,4,'E-5',4),(7,8,'B-5',7),
]

NCH = 10; NPAT = 7
pats = [dict() for _ in range(NPAT)]
def put(pat,row,ch,note=None,inst=None,vol=None,eff=None,epp=None):
    pat[(row,ch)] = (note,inst,vol,eff,epp)

def write_mel(pat, mel, ch, inst, vol, b0, bars, vib=None):
    for (b,r,n,ln) in mel:
        if b < b0 or b >= b0+bars: continue
        row = (b-b0)*16 + r
        put(pat,row,ch,note=N(n),inst=inst,vol=vol)

def write_echo(pat, mel, ch, inst, vol, b0, bars, delay=2):
    for (b,r,n,ln) in mel:
        if b < b0 or b >= b0+bars: continue
        row = (b-b0)*16 + r + delay
        if row >= bars*16: continue
        put(pat,row,ch,note=N(n),inst=inst,vol=vol)

