    for b in range(len(chords)):
        t = ARP_TONES[chords[b]]
        for i in range(16):
            put(pat, b*16+i, 2, note=N(t[i%4]), inst=inst, vol=vol)

def write_bass(pat, chords, inst, vol):
    for b in range(len(chords)):
        R = N(BASS_ROOT[chords[b]])
        seq = [R,R,R,R+12,R,R,R+12,R]
        for i,r in enumerate(range(0,16,2)):
            put(pat, b*16+r, 3, note=seq[i], inst=inst, vol=vol)

