    for b in range(len(chords)):
        r0 = b*16
        put(pat, r0, 8, note=N(PAD_ROOT[chords[b]]), inst=inst, vol=vol)
        for k,fr in ((13,0.72),(14,0.45),(15,0.18)):
            put(pat, r0+k, 8, note=None, inst=None, vol=max(1,int(vol*fr)))

