    for r,v in zip(rows,vols):
        put(pat, bar*16+r, 5, note=N('C-4'), inst=I_SNARE, vol=v)

# ---- P0 intro (Am F C G)
p = pats[0]; c4 = A_SEC[0:4]
for b in range(4):
    t = ARP_TONES[c4[b]]
    for i in range(16):
        put(p, b*16+i, 2, note=N(t[i%4]), inst=I_ARP, vol=[18,24,30,36][b])
for b in range(1,4):
    for r in range(0,16,2): put(p, b*16+r, 6, note=N('C-4'), inst=I_HATC, vol=16+3*b)
write_bass(p, c4, I_BASS, 50)
for b in (2,3):
    for r in (0,4,8,12): put(p, b*16+r, 4, note=N('C-4'), inst=I_KICK, vol=64)
    for r in (2,10): put(p, b*16+r, 7, note=N('C-4'), inst=I_HATO, vol=18)
for r in (4,12): put(p, 48+r, 5, note=N('C-4'), inst=I_SNARE, vol=46)
roll(p, 3, (12,13,14,15), (28,34,42,52))
for b in (2,3): write_pad(p, [c4[b]], I_PAD, 26)

# ---- P1 A first half
p = pats[1]; c4 = A_SEC[0:4]
write_mel(p, A_MEL, 0, I_LEAD, 58, 0, 4)
write_echo(p, A_MEL, 1, I_HARM, 21, 0, 4)
write_arp(p, c4, I_ARP, 34); write_bass(p, c4, I_BASS, 58)
write_drums(p, 4); write_pad(p, c4, I_PAD, 30)

# ---- P2 A second half
p = pats[2]; c4 = A_SEC[4:8]
write_mel(p, A_MEL, 0, I_LEAD, 58, 4, 4)
write_echo(p, A_MEL, 1, I_HARM, 21, 4, 4)
write_arp(p, c4, I_ARP, 34); write_bass(p, c4, I_BASS, 58)
write_drums(p, 4); write_pad(p, c4, I_PAD, 30)

# ---- P3 B first half
p = pats[3]; c4 = B_SEC[0:4]
write_mel(p, B_MEL, 0, I_LEAD, 60, 0, 4)
write_mel(p, B_HARM, 1, I_HARM, 38, 0, 4)
write_arp(p, c4, I_ARP, 27); write_bass(p, c4, I_BASS, 58)
write_drums(p, 4, hc=34, ho=25); write_pad(p, c4, I_PAD, 36)
for b in range(4): put(p, b*16, 9, note=N(ARP_TONES[c4[b]][0])+24, inst=I_BELL, vol=22)

# ---- P4 B second half
p = pats[4]; c4 = B_SEC[4:8]
write_mel(p, B_MEL, 0, I_LEAD, 60, 4, 4)
write_mel(p, B_HARM, 1, I_HARM, 38, 4, 4)
write_arp(p, c4, I_ARP, 27); write_bass(p, c4, I_BASS, 58)
write_drums(p, 4, hc=34, ho=25); write_pad(p, c4, I_PAD, 36)
for b in range(3): put(p, b*16, 9, note=N(ARP_TONES[c4[b]][0])+24, inst=I_BELL, vol=22)
roll(p, 3, (12,13,14,15), (32,38,46,56))

# ---- P5 A first half, climax
p = pats[5]; c4 = A_SEC[0:4]
write_mel(p, A_MEL, 0, I_LEAD, 60, 0, 4)
write_echo(p, A_MEL, 1, I_HARM, 26, 0, 4)
write_arp(p, c4, I_ARP, 36); write_bass(p, c4, I_BASS, 60)
write_drums(p, 4, hc=36, ho=27); write_pad(p, c4, I_PAD, 33)
for b in range(4): put(p, b*16, 9, note=N(ARP_TONES[c4[b]][0])+24, inst=I_BELL, vol=24)

# ---- P6 A second half, climax + turnaround
p = pats[6]; c4 = A_SEC[4:8]
write_mel(p, A_MEL, 0, I_LEAD, 60, 4, 4)
write_echo(p, A_MEL, 1, I_HARM, 26, 4, 4)
write_arp(p, c4, I_ARP, 36); write_bass(p, c4, I_BASS, 60)
write_drums(p, 4, hc=36, ho=27); write_pad(p, c4, I_PAD, 33)
for b in range(3): put(p, b*16, 9, note=N(ARP_TONES[c4[b]][0])+24, inst=I_BELL, vol=24)
roll(p, 3, (12,13,14,15), (32,38,46,56))
put(p, 62, 7, note=N('C-4'), inst=I_HATO, vol=32)

ORDER = list(range(NPAT))
patterns = [(64, pats[i]) for i in range(NPAT)]
write_xm('/workspace/sub/tune.xm', 'KEYGEN A-MINOR', 148, 6, ORDER, patterns,
         INSTRUMENTS, NCH, style='ft2', restart=1)
print('ok: %d instruments, %d patterns' % (len(INSTRUMENTS), NPAT))
