import numpy as np, wave, sys
def load(path):
    w=wave.open(path); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2)[:,0].astype(float)
    return d, w.getframerate()
def peaks(d, sr, t0, t1, n=6, lo=80, hi=8000):
    N=int((t1-t0)*sr); seg=d[int(t0*sr):int(t0*sr)+N]
    seg=seg*np.hanning(N); f=np.fft.rfftfreq(N,1/sr); m=np.abs(np.fft.rfft(seg))
    idx=np.argsort(m)[::-1]; out=[]
    for i in idx:
        if f[i]<lo or f[i]>hi: continue
        if all(abs(f[i]-o)>20 for o in out): out.append(f[i])
        if len(out)>=n: break
    return [round(x,1) for x in out]
